import java.util.*; public class Week04Problem03{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();Arrays.sort(a);for(int i=0;i<n-2;i++){if(i>0&&a[i]==a[i-1])continue;int l=i+1,r=n-1;while(l<r){long q=(long)a[i]+a[l]+a[r];if(q==0){System.out.println(a[i]+" "+a[l]+" "+a[r]);int u=a[l],v=a[r];while(l<r&&a[l]==u)l++;while(l<r&&a[r]==v)r--;}else if(q<0)l++;else r--;}}}}